#!/usr/bin/env node
/**
 * Contract validator: checks the atomic model rules.
 *
 * Checks:
 *   1. Contract integrity: valid tiers, composition rules per tier, no unknown composes references.
 *   2. Component conformance: Custom Element tags used in demo.html files resolve to contract entries.
 *
 * Usage:  node 02-design/library/contract/validate.mjs [file.html ...]
 *         (no args = scans all demo.html files under 02-design/library/elements/)
 *
 * Exit 0 = green. Exit 1 = violations (flagged gaps are reported, not failed).
 */

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve, basename } from 'node:path';

const here    = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, '..', '..', '..');

/* ── locate the contract file ─────────────────────────────────────────────── */
let contractPath;
try {
  const files = readdirSync(here).filter(f => f.endsWith('-contract.js') || f === 'contract.js');
  if (!files.length) throw new Error('No contract file found in ' + here);
  contractPath = join(here, files[0]);
} catch (e) {
  console.error('✗ ' + e.message);
  process.exit(1);
}

/* ── load the contract ────────────────────────────────────────────────────── */
let contract;
try {
  const mod = await import(contractPath);
  contract = mod.contract;
  if (!Array.isArray(contract)) throw new Error('"contract" export must be an array.');
} catch (e) {
  console.error('✗ Could not load contract: ' + e.message);
  process.exit(1);
}

const VALID_TIERS = ['atom', 'molecule', 'organism'];
const byElement   = Object.fromEntries(contract.map(c => [c.element, c]));
const byName      = Object.fromEntries(contract.map(c => [c.name, c]));
const problems    = [];
const notes       = [];

/* ── 1. contract integrity ────────────────────────────────────────────────── */
for (const entry of contract) {
  const { element, name, atomic, composes = [], gap } = entry;

  if (atomic === 'template' || atomic === 'page') {
    problems.push(`${element}: "${atomic}" entries are not permitted in the contract. Templates and pages are layout-layer deliverables, not Custom Elements (atomic model Rule F).`);
    continue;
  }

  if (!VALID_TIERS.includes(atomic))
    problems.push(`${element}: invalid tier "${atomic}"`);

  for (const child of composes) {
    if (!byElement[child] && !byName[child])
      problems.push(`${element}: composes unknown component "${child}"`);
  }

  const resolvedComposes = composes.map(c => byElement[c] || byName[c]).filter(Boolean);

  if (atomic === 'atom' && composes.length)
    problems.push(`${element} (atom) must compose nothing, but composes: ${composes.join(', ')}`);

  if (atomic === 'molecule') {
    const nonAtoms = resolvedComposes.filter(c => c.atomic !== 'atom');
    if (nonAtoms.length)
      problems.push(`${element} (molecule) may compose only atoms; offending: ${nonAtoms.map(c => c.element).join(', ')}`);
  }

  if (atomic === 'organism') {
    const hasMolecule = resolvedComposes.some(c => c.atomic === 'molecule');
    if (!hasMolecule)
      problems.push(`${element} (organism) must compose >= 1 molecule; composes: ${composes.join(', ') || '(none)'}`);
  }

  if (gap) notes.push(`flagged gap (${element}): ${gap}`);
}

/* ── 2. component conformance ─────────────────────────────────────────────── */
function collectHtmlFiles(args) {
  if (args.length) return args.map(a => resolve(process.cwd(), a));
  const componentsDir = resolve(here, '..', 'elements');
  const out = [];
  (function walk(dir) {
    let entries;
    try { entries = readdirSync(dir); } catch { return; }
    for (const entry of entries) {
      const p = join(dir, entry);
      if (statSync(p).isDirectory()) { walk(p); }
      else if (entry === 'demo.html') { out.push(p); }
    }
  })(componentsDir);
  return out;
}

const prefix    = contract[0]?.prefix ?? 'ds';
const tagRe     = new RegExp(`<(${prefix}-[a-z0-9-]+)`, 'gi');
let   usedTotal = 0;

for (const file of collectHtmlFiles(process.argv.slice(2))) {
  let html;
  try { html = readFileSync(file, 'utf8'); } catch { continue; }
  const seen = new Set();
  let m;
  while ((m = tagRe.exec(html))) seen.add(m[1].toLowerCase());
  for (const tag of seen) {
    usedTotal++;
    if (!byElement[tag])
      problems.push(`${basename(file)} (${file}): uses <${tag}> which is not in the contract`);
  }
}

/* ── report ───────────────────────────────────────────────────────────────── */
const tiers = contract.reduce((acc, c) => {
  acc[c.atomic] = (acc[c.atomic] || 0) + 1;
  return acc;
}, {});

console.log(
  `Contract: ${contract.length} components ` +
  `(${tiers.atom || 0} atoms, ${tiers.molecule || 0} molecules, ` +
  `${tiers.organism || 0} organisms).`
);
if (usedTotal > 0) console.log(`Demo files checked: ${usedTotal} tag usages.`);
notes.forEach(n => console.log('  • ' + n));

if (problems.length) {
  console.error(`\n✗ ${problems.length} violation(s):`);
  problems.forEach(p => console.error('  - ' + p));
  process.exit(1);
}
console.log('\n✓ Atomic model valid. All tags in demo files resolve to contract entries.');

