const ASSETS = new URL('../icon/assets/', import.meta.url).href;

class ZimmAddToWishlist extends HTMLElement {
  static get observedAttributes() {
    return ['selected'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._onClick = this._onClick.bind(this);
  }

  connectedCallback() {
    this._render();
    this.shadowRoot.addEventListener('click', this._onClick);
  }

  disconnectedCallback() {
    this.shadowRoot.removeEventListener('click', this._onClick);
  }

  attributeChangedCallback() { this._render(); }

  _onClick() {
    if (this.hasAttribute('selected')) {
      this.removeAttribute('selected');
    } else {
      this.setAttribute('selected', '');
    }
    this.dispatchEvent(new CustomEvent('zimm-wishlist-change', {
      bubbles: true,
      detail: { selected: this.hasAttribute('selected') }
    }));
  }

  _render() {
    const selected = this.hasAttribute('selected');
    const label = selected ? 'Remove from wishlist' : 'Add to wishlist';
    const src = selected
      ? `${ASSETS}wishlist-selected.svg`
      : `${ASSETS}wishlist.svg`;

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-flex; }
        button {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          width: var(--zimm-icon-size-lg);
          height: var(--zimm-icon-size-lg);
        }
        button:focus-visible {
          outline: var(--zimm-border-width-default) solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }
        img { display: block; width: 100%; height: 100%; }
      </style>
      <button aria-label="${label}" aria-pressed="${selected}">
        <img src="${src}" alt="" aria-hidden="true" draggable="false">
      </button>
    `;
  }
}

customElements.define('zimm-add-to-wishlist', ZimmAddToWishlist);

