class ZimmFooter extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
  }

  _render() {
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        * { box-sizing: border-box; }

        footer {
          background-color: var(--zimm-color-bg-inverse);
          width: 100%;
        }

        /* ---- Main grid: mobile default ---- */
        .main {
          display: grid;
          grid-template-columns: 1fr;
          grid-template-rows: auto auto auto;
          padding: var(--zimm-scale-1200) var(--zimm-scale-800) 0;
        }

        .subscribe { grid-column: 1; grid-row: 1; padding-bottom: var(--zimm-scale-600); }
        .links     { grid-column: 1; grid-row: 2; }
        .logo-area { grid-column: 1; grid-row: 3; padding: var(--zimm-scale-1000) 0; }

        /* ---- Subscribe ---- */
        .label {
          margin: 0 0 var(--zimm-scale-600);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse-muted);
        }

        .body-text {
          margin: 0 0 var(--zimm-scale-1200);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-inverse);
        }

        .email-field {
          display: flex;
          align-items: center;
          justify-content: space-between;
          border-bottom: 1px solid var(--zimm-color-text-inverse);
          padding-bottom: var(--zimm-scale-200);
        }

        .email-input {
          flex: 1;
          background: transparent;
          border: none;
          outline: none;
          padding: 0;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          color: var(--zimm-color-text-inverse);
        }

        .email-input::placeholder {
          color: var(--zimm-color-text-inverse);
          opacity: 1;
        }

        .email-submit {
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          display: flex;
          align-items: center;
          color: var(--zimm-color-text-inverse);
        }

        .email-submit:focus-visible {
          outline: 2px solid var(--zimm-color-text-inverse);
          outline-offset: 2px;
        }

        /* ---- Links: mobile 2-col grid ---- */
        .links {
          display: grid;
          grid-template-columns: 1fr 1fr;
          column-gap: var(--zimm-scale-600);
          row-gap: var(--zimm-scale-600);
          padding: var(--zimm-scale-1200) 0;
          border-top: 1px solid var(--zimm-color-grey-700);
          border-bottom: 1px solid var(--zimm-color-grey-700);
        }

        /* Mobile column placement: About + Contact left, Help right */
        .link-group:nth-child(1) { grid-column: 1; grid-row: 1; }
        .link-group:nth-child(2) { grid-column: 1; grid-row: 2; }
        .link-group:nth-child(3) { grid-column: 2; grid-row: 1 / span 2; }

        .group-label {
          margin: 0 0 var(--zimm-scale-600);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse-muted);
        }

        ul {
          list-style: none;
          padding: 0;
          margin: 0;
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-400);
        }

        ul a {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse);
          text-decoration: none;
        }

        ul a:hover { color: var(--zimm-color-text-inverse-muted); }

        /* ---- Logo ---- */
        .logo-area { display: flex; }

        /* ---- Bottom bar ---- */
        .bottom-bar {
          background-color: var(--zimm-color-bg-inverse-deep);
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: var(--zimm-scale-600) var(--zimm-scale-800);
          flex-wrap: wrap;
          gap: var(--zimm-scale-300);
        }

        .locale {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-4xs);
          line-height: var(--zimm-font-lineheight-4xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse);
          white-space: nowrap;
        }

        .legal {
          display: flex;
          align-items: center;
          gap: var(--zimm-scale-500);
          flex-wrap: wrap;
          justify-content: flex-end;
        }

        .legal span,
        .legal a {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-4xs);
          line-height: var(--zimm-font-lineheight-4xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse-muted);
          text-decoration: none;
          white-space: nowrap;
        }

        /* Mobile: hide legal links, keep copyright only */
        .legal-link { display: none; }

        /* ---- Tablet: 768px+ ---- */
        @media (min-width: 768px) {
          .main {
            display: grid;
            grid-template-columns: 329px 1fr;
            grid-template-rows: auto auto;
            padding: var(--zimm-scale-1000) var(--zimm-scale-1000) 0;
            gap: 0 var(--zimm-scale-1200);
          }

          .subscribe {
            grid-column: 1;
            grid-row: 1;
            padding-bottom: var(--zimm-scale-1000);
          }

          .logo-area {
            grid-column: 1;
            grid-row: 2;
            padding: 0 0 var(--zimm-scale-1000);
            align-items: flex-end;
          }

          .links {
            grid-column: 2;
            grid-row: 1 / span 2;
            display: flex;
            flex-direction: row;
            justify-content: flex-end;
            align-items: flex-start;
            gap: var(--zimm-scale-1000);
            border-top: none;
            border-bottom: none;
            padding: 0 0 var(--zimm-scale-1000);
          }

          .legal-link { display: inline; }

          .bottom-bar {
            padding: var(--zimm-scale-600) var(--zimm-scale-1000);
          }
        }

        /* ---- Desktop: 1024px+ ---- */
        @media (min-width: 1024px) {
          .links { gap: var(--zimm-scale-1200); }
        }
      </style>

      <footer role="contentinfo">
        <div class="main">

          <div class="subscribe">
            <p class="label">Stay in Touch</p>
            <p class="body-text">Subscribe to receive news on our latest collections, products, fashion shows and collaborations.</p>
            <div class="email-field">
              <input type="email" class="email-input" placeholder="Email" aria-label="Email address">
              <button class="email-submit" type="button" aria-label="Subscribe">
                <zimm-icon type="arrow-link" size="16" aria-hidden="true"></zimm-icon>
              </button>
            </div>
          </div>

          <div class="logo-area">
            <zimm-logo variant="inverse"></zimm-logo>
          </div>

          <div class="links">
            <div class="link-group">
              <p class="group-label">About</p>
              <ul>
                <li><a href="#">Our Story</a></li>
                <li><a href="#">Careers</a></li>
                <li><a href="#">Sustainability</a></li>
                <li><a href="#">Acknowledgement of Country</a></li>
              </ul>
            </div>
            <div class="link-group">
              <p class="group-label">Contact</p>
              <ul>
                <li><a href="#">866 688 5656</a></li>
                <li><a href="#">Chat with Us</a></li>
                <li><a href="#">Store Finder</a></li>
                <li><a href="#">Socials</a></li>
              </ul>
            </div>
            <div class="link-group">
              <p class="group-label">Help</p>
              <ul>
                <li><a href="#">Orders &amp; Returns</a></li>
                <li><a href="#">Submit a Return</a></li>
                <li><a href="#">FAQs</a></li>
                <li><a href="#">Care Guide</a></li>
                <li><a href="#">Appointments</a></li>
                <li><a href="#">Gifting</a></li>
                <li><a href="#">Brand Protection</a></li>
              </ul>
            </div>
          </div>

        </div>

        <div class="bottom-bar">
          <span class="locale">United States (USD) / Eng</span>
          <div class="legal">
            <span>Copyright &copy; 2026 Zimmermann</span>
            <a href="#" class="legal-link">Accessibility</a>
            <a href="#" class="legal-link">Privacy Policy</a>
            <a href="#" class="legal-link">Terms &amp; Conditions</a>
            <a href="#" class="legal-link">Modern Slavery</a>
            <a href="#" class="legal-link">Cookie Settings</a>
          </div>
        </div>
      </footer>
    `;
  }
}

customElements.define('zimm-footer', ZimmFooter);

