class ZimmNavItem extends HTMLElement {
  static get observedAttributes() {
    return ['label', 'active'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
  }

  attributeChangedCallback() {
    this._render();
  }

  _render() {
    const label = this.getAttribute('label') || '';
    const active = this.hasAttribute('active');

    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: inline-flex;
          align-items: center;
        }
        a {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          text-decoration: none;
          color: var(--zimm-color-text-default);
          white-space: nowrap;
          height: 20px;
          display: inline-flex;
          align-items: center;
          border-bottom: 1px solid transparent;
          padding-bottom: 2px;
          cursor: pointer;
          transition: border-color 150ms ease;
        }
        :host([active]) a,
        a:hover {
          border-bottom-color: var(--zimm-color-border-focus);
        }
      </style>
      <a href="#" aria-current="${active ? 'true' : 'false'}">${label}</a>
    `;
  }
}

customElements.define('zimm-nav-item', ZimmNavItem);

