names.forEach((n,i) => {
  const derived = n.toLowerCase();
  const ok = derived === folders[i];
  console.log(n.padEnd(15), '->', derived.padEnd(15), 'actual folder:', folders[i].padEnd(18), ok ? 'OK' : '*** MISMATCH ***');
});
"

